namespace HelloHttpServer
{
    class Program
    {
        static void Main(string[] args)
        {
            // Créez un objet HttpListener
            HttpListener listener = new HttpListener();

            // Configurez le serveur pour écouter sur le port 8080
            listener.Prefixes.Add("http://localhost:8080/");

            // Démarrez le serveur
            listener.Start();

            Console.WriteLine("Serveur HTTP démarré. Vous pouvez accéder à la page 'Hello' en tappedant http://localhost:8080/ dans votre navigateur...");

            // Attendre les requêtes
            while (true)
            {
                HttpListenerContext context = listener.GetContext();
                HttpListenerRequest request = context.Request;

                // Traitement de la requête
                if (request.Url.AbsolutePath == "/")
                {
                    string response = "<html><body>Hello from C#!</body></html>";
                    context.Response.ContentType = "text/html";
                    context.Response.ContentLength64 = Encoding.UTF8.GetBytes(response).Length;
                    using (System.IO.Stream outstream = context.Response.OutputStream)
                    {
                        using (System.IO.StreamWriter writer = new System.IO.StreamWriter(outstream))
                        {
                            writer.Write(response);
                        }
                    }
                }
                else
                {
                    context.Response.StatusCode = 404;
                    context.Response.StatusDescription = "Page not found";
                }
            }
        }
    }
}
